func productExceptSelf(nums []int) []int {
	ans := make([]int, len(nums))
	for i := range ans {
		ans[i] = 1
	}
	tmp := 1
	for i := 1; i < len(nums); i++ {
		ans[i] = ans[i-1] * nums[i-1] // 下三角
	}
	for i := len(nums) - 2; i >= 0; i-- {
		tmp *= nums[i+1] // 上三角
		ans[i] *= tmp    // 下三角 * 上三角
	}
	return ans
}
